INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pinball', 'This cartridge contains eight exciting variations of the pinball game for either one or two to play. As in the case of the biggest versions in the amusement centres, the idea is to use the flippers to keep the ball in play for as long as possible and score a maximum in the way of points.' FROM games WHERE igdb_id = 56075 ON CONFLICT (game_id, language_code) DO NOTHING;
