INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('blisterball-and-mad-bomber', 287380, '1981-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7t95.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scqnf3.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blisterball! & Mad Bomber!', 'Blisterball! & Mad Bomber! are a series of two 1 or 2-player arcade games for the Apple II. Both games allow for single-player, as well as 2-player cooperative gameplay. Also allows for 2-player competitive play, where 2 players compete for a high score. The player controls a small ship or cannon on the bottom of the screen, which can move horizontally left and right using the Apple game paddles. The ship fires vertically upwards. In Blisterball!, the goal is to shoot down bouncing balls as they bounce out of the chamber above the player. If the player is hit by a ball, they are damaged, and they fall into the drain below if they are struck 3 times. There is also a series of blister balls, which can be shot for bonus points. In Mad Bomber!, the player must shoot bombs as they descend from slots above. If a bomb strikes the bottom of the screen, the player loses a point. 10 points lost, and it''s game over. The player must regularly refill their ammo by bringing their ship to the edge of the screen, and if the player is caught in the explosion of a bomb, they lose 10 ammo.' FROM games WHERE igdb_id = 287380 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 287380 AND ge.slug = 'arcade' ON CONFLICT DO NOTHING;
