INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Adventure in Time', 'Adventure in Time is a text-based adventure game, that requires the player to adventure through multiple time zones. All commands are typed via VERB NOUN entries. The player must gather inventory and solve text-based puzzles, and can hold up to 6 items at a time. The player starts out in the future, after being drugged and left incapacitated by the criminal responsible. They must explore a variety of time zones, including Stonehenge, ancient Rome, and the Mesozoic era, to gather the missing pieces of the all powerful weapon before Nostradamus can construct it, and use it to destroy the human race.' FROM games WHERE igdb_id = 205774 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 205774 AND ge.slug = 'adventure' ON CONFLICT DO NOTHING;
