INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('alien-rain', 12251, '1981-03-15', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9lga.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/fxdwylome7x0jvpuf1m8.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alien Rain', 'A game based on the Alien movie. Alien Rain (also called Apple Galaxian) is a clone of the arcade game Galaxian. It is a shoot-''em-up where a formation of aliens attack your starfighter at the bottom of the screen. The alien peel off from the group, singly or in formation and attack you, the pattern depending on what type of alien it is. Once all aliens are killed, you move to a new level, indicated by a flag at the bottom. The game was released for the Apple II as Alien Rain.' FROM games WHERE igdb_id = 12251 ON CONFLICT (game_id, language_code) DO NOTHING;
