INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Manhole', 'Manhole is a Game & Watch game. In the game, you must save pedestrians from falling into manholes by covering them up. If one falls through, you will lose and will have to start over.' FROM games WHERE igdb_id = 100229 ON CONFLICT (game_id, language_code) DO NOTHING;
