INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('empire-of-the-over-mind', 18470, '1981-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9j0j.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Empire of the Over-Mind', 'In this text adventure it is the player''s goal to reach the red planet that gloomily hangs above its alter ego''s head. Contrary to most text adventures of its time the player does not use directions like north, south, up etc. to maneuver through the game world. Instead he gives instructions to head to a specific location. Therefore the player has the ability to look ahead. Clues to the solution of the game are hidden in a poem which came along with the game.' FROM games WHERE igdb_id = 18470 ON CONFLICT (game_id, language_code) DO NOTHING;
