INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pleiads', 40009, '1981-04-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/k9kgmd5eqz77g6bcyfia.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scpzqg.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pleiads', 'Pleiads is a multi-stage space shoot ''em up in which enemy ships fly at the player in waves in a similar fashion to games like Galaxian and Phoenix. Ships emerge from a mothership at the top of the screen and swoop downwards in a series of patterns which players must anticipate as they shoot the ships and avoid being obliterated by the Martian onslaught. There are four stages in the game. In the first stage the Earth space ship must defend the space station from Martian invaders who have the ability to transform from flying invaders, to walking invaders who build walls across the Earth city; these barriers must be destroyed. At the end of stage one the Earth space ship flies to the top of the screen to prepare to meet stage two. In the second stage the player encounters eight space monsters who must be hit directly on center to be destroyed before moving onto stage three. In this stage invaders emerge form a space ship at the top of the screen and swoop down on the player in sweeping attacks. In the final wave the player has to navigate through parked spaceships to dock on a landing pad as the screen scrolls downwards. Extra points can be gained in this stage by collecting flags as the player moves towards the landing corridor.' FROM games WHERE igdb_id = 40009 ON CONFLICT (game_id, language_code) DO NOTHING;
