INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pulsar II', 'A single screen shoot''em up written by Nasir Gebelli and published by Sirius Software for the Apple II computers. The player controls a flying saucer, that can rotate clockwise or anticlockwise around a pulsar, with the aim to destroy the shields around the pulsar and finally the pulsar itself.' FROM games WHERE igdb_id = 59557 ON CONFLICT (game_id, language_code) DO NOTHING;
