INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Octopus', 'Octopus is a Game & Watch game that was released on the G&W widescreen series. In the game, you, the diver, must get around an octopus whom is trying to capture you and get to the treasure. When Mr. Game & Watch returns to the salvage ship, he gets three extra points. The player''s three chances are measured by extra divers on the savage ship. When one is attacked by the Octopus'' tentacles, another takes his place.' FROM games WHERE igdb_id = 145159 ON CONFLICT (game_id, language_code) DO NOTHING;
