INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('donkey-dot-bas', 19382, '1981-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2ord.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/eskolq4niypwvllijwuh.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Donkey.Bas', 'Donkey, often known by its file name Donkey.Bas, is a computer game written in 1981 and included with early versions of the PC DOS operating system distributed with the original IBM PC. It is a driving game in which the player must avoid hitting donkeys. The game was written by Microsoft co-founder Bill Gates and Neil Konzen.' FROM games WHERE igdb_id = 19382 ON CONFLICT (game_id, language_code) DO NOTHING;
