INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('snafu', 5697, '1981-10-15', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1pgl.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar11c2.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Snafu', 'The contest is on! Create a maze to corner your opponents...before you are cornered yourself. Split-second reflexes keep your trail in motion -- while blocking your opponent and/or the computer in a trap from which there is no escape. Or direct a hungry serpent after your opponent, and bite his tail off before he bites yours. It''s a twisting tangle which only the swift survive. 16 game variations put you in control. Trap Games (12 variations) -- To keep your trail moving without colliding -- and to block your opponents'' trails so that they are forced into collisions. Trails that collide with others, with the edge of the picture, with obstacles or themselves are eliminated. Bite Games (4 variations) -- To make contact between the head of your serpent and the tail of your opponent''s serpent, "biting" off one link with each contact. The winner is the surviving serpent.' FROM games WHERE igdb_id = 5697 ON CONFLICT (game_id, language_code) DO NOTHING;
