INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Helmet', 'Helmet is a Game & Watch game that was released in 1981. In the game, you have to run from one house to the house across from it without getting hit by falling tools that your enemies is throwing at you. Sometimes the door on the other house will close, making you run around until it opens.' FROM games WHERE igdb_id = 91702 ON CONFLICT (game_id, language_code) DO NOTHING;
