INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Softporn Adventure', 'A text based adventure game released in 1981 and has similar content to "Leisure Suit Larry in the Land of the Lounge Lizards" developed by Al Lowe which is based on "Softporn Adventure". It was ported to PC in 1991 and has also been included in some Leisure Suit Larry Collection editions.' FROM games WHERE igdb_id = 10679 ON CONFLICT (game_id, language_code) DO NOTHING;
