INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stellar Track', 'Stellar Track is a text- and turn-based strategy game where the player controls a Terran Super Warship that must clear out alien ships from all quadrants of a galaxy. It was a conversion of a college mainframe Star Trek game released by Sears in 1981. It is a suitably primitive game where you have to run scans to locate enemies and starbases on a 6 x 6 galactic map. You run scans to find the enemies then must warp to their quadrant to confront them with either phasers or photon torpedoes. You use the joystick to determine the numerals of where you intend you to travel to.' FROM games WHERE igdb_id = 18427 ON CONFLICT (game_id, language_code) DO NOTHING;
