INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Attack', 'Originally called "Alien Attack," this game pits the player against alien "spores." Although the spores themselves are harmless, they can join together to form giant aliens that chase you down and eat you. To make matters more interesting, scattered around the playing field are a number of "incubators," which can hatch either more spores or, at later levels (or in early levels, in more advanced difficulty levels), more aliens. Use your ship''s weapons to blast the spores before they can make new aliens, and blast any aliens before they can devour you.' FROM games WHERE igdb_id = 44375 ON CONFLICT (game_id, language_code) DO NOTHING;
