INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mickey Mouse', 'There are two Game & Watch games called Mickey Mouse. In this one, which is part of the Panorama series, Mickey has to juggle while balancing on top of a ball. Mickey can lose a life by catching a fire stick instead of a juggling stick or missing catching the juggling stick completely.' FROM games WHERE igdb_id = 175636 ON CONFLICT (game_id, language_code) DO NOTHING;
