INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('fantasy', 94811, '1981-10-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7lb0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc6dmq.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fantasy', 'Fantasy is a simple 2D arcade game. The main hero must rescue his girlfriend as she was kidnapped by pirates. After the rescue, other hijackers appear all the time - the hero is busy non-stop. Each level is different - ballooning, pirate ship, jungles, a village full of savages ...There are no buttons to interact with - only the joystick. Most of the time, the hero must avoid the enemies - but sometimes (for example in the village), he can automatically use a sword.' FROM games WHERE igdb_id = 94811 ON CONFLICT (game_id, language_code) DO NOTHING;
