INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('boxing', 5663, '1981-10-21', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1pfy.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scpzk3.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Boxing', 'Boxing shows a top-down view of two boxers, one white and one black. When close enough, a boxer can hit his opponent with a punch (executed by pressing the fire button on the Atari joystick). This causes his opponent to reel back slightly. Long punches score one point, while closer punches (power punches, from the manual) score two. There are no knockdowns or rounds. A match is completed either when one player lands 100 punches (a "knockout") or two minutes have elapsed (a "decision"). In the case of a decision, the player with the most landed punches is the winner. Ties are possible. While the gameplay is simple, there are subtleties, such as getting an opponent on the "ropes" and "juggling" him back and forth between alternate punches.' FROM games WHERE igdb_id = 5663 ON CONFLICT (game_id, language_code) DO NOTHING;
