INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Thief', 'Players drive a car around a maze collecting greenbacks while being pursued by a number of police cars. Use dollar symbols to make your car invincible and put police cars temporarily out of action. The game uses a continuous loop tape with actual police band radio banter.' FROM games WHERE igdb_id = 23321 ON CONFLICT (game_id, language_code) DO NOTHING;
