INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Korosuke Roller', 'Time to take up your paint brush and paint the town Red (or Green or Orange, or whatever color you happen to have on hand)! A pair of fish are out to stop you but you can roll over them at the overpass. There''s other items that just try to mess up your paint job; you can run over these folks easily (if you catch them).' FROM games WHERE igdb_id = 40225 ON CONFLICT (game_id, language_code) DO NOTHING;
