INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('cartels-and-cutthroats', 22497, '1981-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/vr3cdqvmgiafxf8t9kge.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scpr9o.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cartels & Cutthroats', 'The buck stops with you! Here''s a business game that puts you in charge of your very own multi-million dollar corporation. You''ll get a real taste of power and money, but it''s not going to be easy. You''ll also have to deal with all the responsabilities and headaches that come with such a prestigious position. Your decisiveness will be sorely tested: Do you need to form price cartels or engage in cutthroat competition? Can you react to a competitor''s advertising "blitz" before you lose the competitive edge? Will you decide to automate your factories in order to cut production costs and risk labor''s wrath? How will you handle labor demands during profitable years? What steps will you take when productivity declines during recessions? The proverbial buck certainly stops with you. But think of the rewards! Do your job right and you may make megabucks! Developed by two professionals - one in systems simulation and the other with a master''s degree in business administration - C&C provides a full range of options, from an easy-to-play game for beginners to an advanced version that''ll stump even experienced businessmen. This game is so much fun you may overlook its use as a superb educational tool. Designed for one to six players - with the computer playing up to five positions if you want - CARTELS & CUTTHROATS will prepare you to take on the "real world"!' FROM games WHERE igdb_id = 22497 ON CONFLICT (game_id, language_code) DO NOTHING;
