INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Hand', 'A maze game like Pac-man. You are a ''Hand'' and so are your enemies. Each hand can be Rock (A fist), Paper (Flat) or Scissors (2 fingers extended). Your job is to clear a maze of dots to move to the next level. If you touch an enemy and your ''hand'' beats his, you win, otherwise you lose your current turn.' FROM games WHERE igdb_id = 40351 ON CONFLICT (game_id, language_code) DO NOTHING;
