INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Draco', 'The player controls the movement of his Humanoid by moving it across the surface of a strange planet (Draco), whose treasures (points) are guarded by robots. The Humanoid must appropriate the treasures of Draco by knocking down the obstacles that protect them and defending themselves from the Draco robots that lie in wait for him. For this it has its laser beam, and a limited dose of energy.' FROM games WHERE igdb_id = 151163 ON CONFLICT (game_id, language_code) DO NOTHING;
