INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Memory II / Melodie', 'This cartridge contains eight entertaining teaching programs and game variations on the subject of music. In the first part of each program, notes can be learnt and your own compositions fed into the computer. In the second part, the idea is to memorize tunes and reproduce them correctly. (Two can play or it''s you versus the computer.)' FROM games WHERE igdb_id = 72371 ON CONFLICT (game_id, language_code) DO NOTHING;
