INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crush Roller', 'Make Trax, known in Japan as Crush Roller (クラッシュローラー Kurasshu Rōrā?) is a 1981 arcade game originally developed by Alpha Denshi and published by Kural Samno in Japan. It was later licensed for North American release to Williams, and in Europe to Karateco and Exidy.' FROM games WHERE igdb_id = 39641 ON CONFLICT (game_id, language_code) DO NOTHING;
