INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Galaxy Warrior', 'A top down view space battle against the Klingons. You can rotate your ship and fire rockets to the Klingons but make sure not to hit them. After defeating all the Klingons you can use a wormhole to go the the next galaxy. You can configure the speed and whether the Klingons move or not and you have three ships at your disposal.' FROM games WHERE igdb_id = 152319 ON CONFLICT (game_id, language_code) DO NOTHING;
