INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Winners Circle', 'Cocktail Horse Racing game in which 1 to 4 players can participate in determining the 1st and 2nd place winning horse from 7 that race against one another Winners Circle was produced by Corona in 1981. Corona released 2 machines in our database under this trade name, starting in 1981. Corona was based in United States. Other machines made by Corona during the time period Winners Circle was produced include:' FROM games WHERE igdb_id = 308128 ON CONFLICT (game_id, language_code) DO NOTHING;
