INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Armored Car', 'You drive a money van (the armoured car) through as it scrolls from right to left. Some intersections are marked with directions. You pick up money to deliver to banks while avoiding criminals by dropping saw horses on the road. Fuel levels must be replenished at gas stations along the way.' FROM games WHERE igdb_id = 40015 ON CONFLICT (game_id, language_code) DO NOTHING;
