INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('fantasy-games', 319578, '1981-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8xgn.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scu5hl.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fantasy Games', 'Fantasy Games is a double games pack containing the following adventure games: Perilous Swamp: Deep in a Perilous Swamp, your quest is to find and rescue a Princess held captive by an evil Wizard before escaping out of the swamp. You are presented with a map of your surroundings and text tells you any objects you can see. As you move around the swamp you will encounter various creatures who you can fight, run from or bribe (if you have enough treasure). If you choose to fight then you decide how many combat strength points to use. Spells can be found and used to help you on your quest. Sorcerer''s Island: Similar to Perilous Swamp, this time you are on an island and you must attempt to leave it. One difference is you can encounter people like the King of the Dwarves and the Grand Sorcerer himself to help you.' FROM games WHERE igdb_id = 319578 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 319578 AND ge.slug = 'adventure' ON CONFLICT DO NOTHING;
