INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('qs-defender', 319594, '1981-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8xh7.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scu5im.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'QS Defender', 'QS Defender is a side scrolling shooter that although it is inspired by it, lacks many features of the arcade game Defender. This version is constantly scrolling left to right and there is no option to turn around and move in the opposite direction. The player can move up and down, fire and use thrust to increase the movement speed forward. There is only one enemy type and each one killed is worth 100 points. Enemies appear in waves. At the start there are just a few but as the player progresses it gets more hectic with up to eight enemies on the screen at once. The player has nine ships. When getting hit the screen goes black for a few seconds before it starts again with a clear screen and one ship less. Once all ships are lost the game has to be restarted through basic.' FROM games WHERE igdb_id = 319594 ON CONFLICT (game_id, language_code) DO NOTHING;
