INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fantasyland 2041 A.D.', 'You are visiting Fantasyland - the theme park of the future. Within Fantasyland there are six different themed areas: Congoland (Africa themed adventure exhibit), Arabia (1001 nights inspired exhibit), King Arthur (middle age Arthurian legend inspired exhibit), Olympus (a Greek mythology inspired exhibit), Captain Nemo (a Jules Vernes inspired underwater exhibit) and last but not least Dante''s Inferno (an underworld themed exhibit inspired by Dante''s epic poem). You have to travel through all six exhibits in order to safe Lancelot (or Lady Guinevere).' FROM games WHERE igdb_id = 282635 ON CONFLICT (game_id, language_code) DO NOTHING;
