INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'U.S. Ski Team Skiing', 'In U.S. Ski Team Skiing, players race down the hill, avoiding trees and jumping moguls in their path. The game features both slalom and downhill courses. 1 player may race against the clock, or 2 to 6 players can alternate turns and race to see who gets the fastest time, and each race has 3 heats.  Both downhill and slalom courses have 15 different slope grade settings to affect acceleration. 4 different settings for overall game speed are also available.' FROM games WHERE igdb_id = 41449 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 41449 AND ge.slug = 'sport' ON CONFLICT DO NOTHING;
