INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lucifer''s Realm', 'After having died in a hospital you are wrongly sent to Hell. There you find out that Lucifer is faced by an attempt to usurp his reign - by none other than Adolf Hitler. In exchange for or your help to thwart Hitler''s plans, Lucifer will grant you passage to Heaven...' FROM games WHERE igdb_id = 25895 ON CONFLICT (game_id, language_code) DO NOTHING;
