INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Othello', 'Othello is a conversion of the board game. Each player tries to fill the game board with as many discs of his color as possible. On each turn the player places a disc on the board by selecting a location where the opponents discs will become trapped between two of his discs. The trapped discs are flipped over to the players color. The game ends when the board is filled or time runs out, and the player with the greatest number of his color discs on the board wins. Two players can play against each other, or one player against the computer.' FROM games WHERE igdb_id = 54795 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 54795 AND ge.slug = 'card-and-board-game' ON CONFLICT DO NOTHING;
