INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Flip-It', 'The object of this game is to completely fill the board with as many pieces of your color as you can. To do this you must outflank your opponent''s pieces and flip them to your color. Outflanking can occur horizontally, vertically, or diagonally. The game ends when the board is full or when both players can''t move. Whoever has the most pieces wins.' FROM games WHERE igdb_id = 159167 ON CONFLICT (game_id, language_code) DO NOTHING;
