INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Adventure B: Inca Curse', 'Released in 1982, Adventure B: Inca Curse is the second in a series of eight interactive fiction adventures made by Artic Computing. The aim is to explore an Incan temple in order to find golden treasures. There are eight treasures and only six items can be carried in the inventory, so the correct treasures must be collected in order to leave the temple with the maximum score.' FROM games WHERE igdb_id = 45354 ON CONFLICT (game_id, language_code) DO NOTHING;
