INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Arena of Octos', 'Arena of Octos is a single-player, turn-based combat video game for the Apple II and TRS-80 computer families. It was created by Steve Kropinak and Al Johnson in 1981 and published by SoftSide magazine. The player assumes the role of a human space pilot, captured by an aggressive race of green-skinned aliens known as Octons after straying into their space. To win freedom, the human must become a gladiator and engage in physical combat with numerous Octon warriors.' FROM games WHERE igdb_id = 192112 ON CONFLICT (game_id, language_code) DO NOTHING;
