INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tooth Invaders', 'Tooth Invaders is a video game released by Commodore International for its VIC-20 home computer in 1981 and later for the C64 in 1982. It was developed in association with Camelot Marketing Group in order to positively reinforce the pros of brushing, flossing, and healthy dental care. Seen as a fun way to teach children the importance of dental care, players fight as "Plaqueman" to fight plaque using a toothbrush and dental floss. It was also made in association with the American Dental Association, released during National Dental Month, and supported by dentists.' FROM games WHERE igdb_id = 92322 ON CONFLICT (game_id, language_code) DO NOTHING;
