INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Snoggle', 'You are Snoggle, fleeing through a maze of ghosts who will eat you if they catch you. You have to be quick, you need to be bold, to master the eight levels of this fast-action puzzler. Basically, Snoggle is a Pac-Man clone, and one of the earliest ones on the Apple II computer.' FROM games WHERE igdb_id = 172458 ON CONFLICT (game_id, language_code) DO NOTHING;
