INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Parachute', 'Parachute is a game for the Game & Watch where you have to save people from a helicopter and make them land in your boat. You will direct your boat under the person try and let them land safely. If they land in the water, a shark will come and eat them- if this happens three times you will lose and will have to start over.' FROM games WHERE igdb_id = 145158 ON CONFLICT (game_id, language_code) DO NOTHING;
