INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Program Pack 4', 'Program Pack 4 is a double games pack that contains: Breakout: Based on the arcade game where the aim is to remove all the bricks at the top of the screen by moving a bat left or right below and bouncing a ball upwards. If you let the ball pass your bat then you lose one of three lives. Brikthru: Moving a bat left or right and bouncing a ball upwards, you clear the screen with a ball going through a shaded area and bouncing off the top and sides of the screen. If you let the ball pass your bat you lose one of thee lives.' FROM games WHERE igdb_id = 319591 ON CONFLICT (game_id, language_code) DO NOTHING;
