INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Miser''s House', 'This game was first released as Miser for the Commodore PET in 1981. Considering the strict constraints of the early 8-bit machines - the original version only required 16K of memory to run - it was remarkable for its complexity.' FROM games WHERE igdb_id = 25116 ON CONFLICT (game_id, language_code) DO NOTHING;
