INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('800-fathoms', 39338, '1981-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/bx74jsaawok9hmo2np6y.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scmh6c.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '800 Fathoms', 'The player has to guide a submarine armed with torpedoes and missiles through five levels while fighting different underwater terrors. The game play is easy during the first five areas but it gets really tough at the later levels where the underwater landscape "grows" and there is not much space left for maneuvering the submarine. At the end of each area the boss-submarine appears and its firepower is not easy to overcome. US Billiards, the 800 Fathoms maker, released 10 different machines in our database under this trade name, starting in 1973. Other machines made by US Billiards during the time period 800 Fathoms was produced include Ab$cam, Variety, US Billiards, Video Pool, Survival, and Shark.' FROM games WHERE igdb_id = 39338 ON CONFLICT (game_id, language_code) DO NOTHING;
