INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cyborg', 'A science fiction text adventure game in which an artificial intelligence is electronically merged with your body as the result of a scientific experiment. Your mission is to find a source of energy to keep you alive. The game uses a text parser, except for character interaction, during which you choose a question from a predetermined list.' FROM games WHERE igdb_id = 18748 ON CONFLICT (game_id, language_code) DO NOTHING;
