INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('shark-attack', 18749, '1981-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob3uy.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scq5t7.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shark Attack', 'You are a diver in an underwater maze. Throughout the maze are valuable diamonds, and your goal is to retrieve as many as you can. In the middle of the screen is a shark cage where you begin. As you collect diamonds you need to bring them back to the shark cage in order to earn points. Swimming back and forth constantly is a deadly shark. If the shark encounters any of the diamonds, it will eat them; likewise you can also be eaten by the shark, causing you to lose a life. You have no defense against the shark, however you are immune if you are in the shark cage and the doors are closed. Somewhere in the maze the Loch Ness monster remains hidden. If you disturb the monster, it will continuously chase you unless you can lead it back into one of the caves located in the corners of the screen.' FROM games WHERE igdb_id = 18749 ON CONFLICT (game_id, language_code) DO NOTHING;
