INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Torpedo Fire', 'Torpedo Fire is a turn-based tactical game of WW2 naval warfare focused on submarine vs. destroyer combat. The player may take the role of either a submarine commander or a destroyer captain in any side of the conflict, while at the same time send orders to other ships in the player''s command. The game allows playing against a fellow player (hot-seat multiplayer) or the computer AI in turns that simulate 60 minutes of actual combat.' FROM games WHERE igdb_id = 23998 ON CONFLICT (game_id, language_code) DO NOTHING;
