INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Videocart-26: Alien Invasion', 'In this Space Invaders variant, the player controls a gun turret at the bottom of the screen and fires missiles at incoming alien ships. The turret can move both left and right and hide behind three protective barriers. The alien invaders move left and right, fire missiles at the player, and slowly approach the planet surface - if they land, the player loses the game. Every once in a while, an alien mothership will fly across the top of the screen and shooting it will give the player extra points. The goal of the game is to destroy all alien ships in each attacking wave and score as many points as possible. The game ends when players lose their three lives.' FROM games WHERE igdb_id = 18604 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 18604 AND ge.slug = 'arcade' ON CONFLICT DO NOTHING;
