INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ghost-hunter--5', 321359, '1981-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co93xn.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scud38.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ghost Hunter', 'Ghost Hunter is an Atari 400/800 game that puts a unique spin on the classic Pac-Man formula. Set in a haunted mansion on Huckleberry Hill, players control a character tasked with eliminating ghosts by consuming dots in a maze. The game supports both single and simultaneous two-player modes, pitting players against four increasingly aggressive ghosts across 15 pre-designed levels and a random level generator. Ghost Hunter introduces innovative features such as an "instant-hide" ability, allowing players to temporarily vanish to evade ghosts once per life. Additionally, players can collect character fragments scattered throughout the maze to earn extra lives. With its familiar maze-navigation gameplay, power pellets for ghost vulnerability, and progressive difficulty, Ghost Hunter offers a fresh take on the beloved arcade classic while adding its own supernatural twist.' FROM games WHERE igdb_id = 321359 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 321359 AND p.igdb_id = 65 ON CONFLICT DO NOTHING;
